#include <iostream>

struct Reading {
  int value;
};

/* тип */ Select(Reading& first, Reading& second, bool use_first) {
  if (use_first) {
    return first.value;
  }
  return second.value;
}

int main() {
  Reading first{3};
  Reading second{8};
  Select(first, second, false) = 12;
  std::cout << first.value << ' ' << second.value;
}
